using UnityEngine;

public class FireballScript : MonoBehaviour
{
    public int damage = 35;
    public int burnDamage = 5;
    public int burnDuration = 3;

    public void Cast(GameObject target)
    {
        target.GetComponent<Stats>().takeDamage(damage);
        target.GetComponent<Stats>().StatusDamage("Burn", burnDuration, burnDamage);
    }
}
